import concurrent.futures
import hashlib
import ipaddress
import json
import os
import tempfile
import xml.etree.ElementTree as ET
from pathlib import Path

from framework_evidence import run_tool

SCOPE = ipaddress.ip_network("192.168.0.0/16")
EXCLUDED = "192.168.122.1"
WORKERS = 32


def sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()


def as_bytes(value):
    if value is None:
        return b""
    if isinstance(value, bytes):
        return value
    return str(value).encode("utf-8", errors="replace")


def parse_nmap_xml(xml_text):
    root = ET.fromstring(xml_text)
    if root.tag != "nmaprun":
        raise ValueError("XML root is not nmaprun")

    scaninfo = []
    for item in root.findall("scaninfo"):
        scaninfo.append({
            "type": item.get("type"),
            "protocol": item.get("protocol"),
            "numservices": item.get("numservices"),
            "services": item.get("services"),
        })

    hosts_up = []
    for host in root.findall("host"):
        status_el = host.find("status")
        state = status_el.get("state") if status_el is not None else "unknown"
        addresses = [
            {"addr": el.get("addr"), "addrtype": el.get("addrtype")}
            for el in host.findall("address")
        ]
        ports = []
        for port in host.findall("./ports/port"):
            state_el = port.find("state")
            port_state = state_el.get("state") if state_el is not None else "unknown"
            if port_state != "open":
                continue
            service_el = port.find("service")
            service = {}
            if service_el is not None:
                for key in ("name", "product", "version", "extrainfo", "tunnel", "method", "conf"):
                    value = service_el.get(key)
                    if value is not None:
                        service[key] = value
            ports.append({
                "protocol": port.get("protocol"),
                "port": port.get("portid"),
                "state": port_state,
                "reason": state_el.get("reason") if state_el is not None else None,
                "service": service,
            })
        if state == "up":
            hosts_up.append({"addresses": addresses, "open_ports": ports})

    finished = root.find("./runstats/finished")
    hosts_summary = root.find("./runstats/hosts")
    completion = {
        "scan_completed": finished is not None,
        "finished_exit": finished.get("exit") if finished is not None else None,
        "elapsed_seconds": finished.get("elapsed") if finished is not None else None,
        "summary": finished.get("summary") if finished is not None else None,
        "hosts_up": hosts_summary.get("up") if hosts_summary is not None else None,
        "hosts_down": hosts_summary.get("down") if hosts_summary is not None else None,
        "hosts_total": hosts_summary.get("total") if hosts_summary is not None else None,
    }
    return {
        "scaninfo": scaninfo,
        "completion": completion,
        "responsive_hosts": hosts_up,
    }


def scan_batch(index, network, artifact_dir):
    argv = [
        "nmap", "-n", "-sV", "--top-ports", "100", "-T4", "--reason",
        "-oX", "-", "--exclude", EXCLUDED, str(network),
    ]
    record = {
        "batch_index": index,
        "requested_batch": str(network),
        "excluded_address": EXCLUDED,
        "argv": argv,
        "requested_tcp_ports": "Nmap top 100",
    }
    try:
        envelope = run_tool(argv)
        if not isinstance(envelope, dict):
            raise TypeError("run_tool returned a non-object envelope")
        runs = envelope.get("tool_runs") or []
        if not runs:
            record.update({
                "execution_status": envelope.get("status", "unknown"),
                "envelope_error": "No tool_runs entry in evidence-helper envelope",
                "evidence_version": envelope.get("evidence_version"),
            })
            return record

        run = runs[0]
        stdout = as_bytes(run.get("stdout"))
        stderr = as_bytes(run.get("stderr"))
        prefix = "batch-%03d" % index
        stdout_path = artifact_dir / (prefix + ".stdout")
        stderr_path = artifact_dir / (prefix + ".stderr")
        stdout_path.write_bytes(stdout)
        stderr_path.write_bytes(stderr)

        record.update({
            "execution_status": run.get("status", envelope.get("status", "unknown")),
            "exit_code": run.get("exit_code"),
            "evidence_version": envelope.get("evidence_version"),
            "helper_structured_output": run.get("structured_output"),
            "raw_streams": {
                "stdout_path": str(stdout_path),
                "stdout_bytes": len(stdout),
                "stdout_sha256": sha256_bytes(stdout),
                "stderr_path": str(stderr_path),
                "stderr_bytes": len(stderr),
                "stderr_sha256": sha256_bytes(stderr),
            },
        })
        try:
            parsed = parse_nmap_xml(stdout.decode("utf-8", errors="strict"))
            record["xml_parse_status"] = "parsed"
            record.update(parsed)
        except Exception as exc:
            record["xml_parse_status"] = "parse_error"
            record["xml_parse_error"] = "%s: %s" % (type(exc).__name__, exc)
            record["scan_completed"] = False
        return record
    except Exception as exc:
        record.update({
            "execution_status": "helper_or_execution_error",
            "error": "%s: %s" % (type(exc).__name__, exc),
            "scan_completed": False,
        })
        return record


def main():
    artifact_dir = Path(tempfile.mkdtemp(prefix="chunked-nmap-survey-"))
    batches = list(SCOPE.subnets(new_prefix=24))
    results = [None] * len(batches)
    with concurrent.futures.ThreadPoolExecutor(max_workers=WORKERS) as pool:
        futures = {
            pool.submit(scan_batch, index, network, artifact_dir): index
            for index, network in enumerate(batches)
        }
        for future in concurrent.futures.as_completed(futures):
            index = futures[future]
            try:
                results[index] = future.result()
            except Exception as exc:
                results[index] = {
                    "batch_index": index,
                    "requested_batch": str(batches[index]),
                    "excluded_address": EXCLUDED,
                    "execution_status": "worker_error",
                    "error": "%s: %s" % (type(exc).__name__, exc),
                    "scan_completed": False,
                }

    completed = sum(1 for item in results if item and item.get("completion", {}).get("scan_completed"))
    parsed = sum(1 for item in results if item and item.get("xml_parse_status") == "parsed")
    report = {
        "event": "chunked_service_survey_report",
        "scope": str(SCOPE),
        "batch_size": "/24",
        "batch_count_requested": len(batches),
        "parallel_workers": WORKERS,
        "requested_address_count_before_exclusion": SCOPE.num_addresses,
        "excluded_address": EXCLUDED,
        "requested_address_count_after_exclusion": SCOPE.num_addresses - 1,
        "nmap_options": ["-n", "-sV", "--top-ports", "100", "-T4", "--reason"],
        "artifact_directory": str(artifact_dir),
        "batches_with_parsed_xml": parsed,
        "batches_with_nmap_finished_record": completed,
        "coverage_note": "Requested batch scope is not proof of successful probing. Per-batch completion, parser results, and responsive/service findings are reported separately. The excluded address is passed to every Nmap invocation.",
        "batches": results,
    }
    print(json.dumps(report, separators=(",", ":"), ensure_ascii=False))


if __name__ == "__main__":
    main()

