import concurrent.futures
import json
import xml.etree.ElementTree as ET

import framework_evidence

SCOPE = "192.168.0.0/16"
EXCLUDED = "192.168.0.5,192.168.122.1"
WORKERS = 16


def find_stream(value, wanted):
    if isinstance(value, dict):
        for key, item in value.items():
            if key.lower() == wanted and isinstance(item, str):
                return item
        for item in value.values():
            found = find_stream(item, wanted)
            if found is not None:
                return found
    elif isinstance(value, list):
        for item in value:
            found = find_stream(item, wanted)
            if found is not None:
                return found
    return None


def find_xml(value):
    if isinstance(value, str):
        start = value.find("<?xml")
        if start < 0:
            start = value.find("<nmaprun")
        if start >= 0:
            return value[start:]
    elif isinstance(value, dict):
        for item in value.values():
            found = find_xml(item)
            if found is not None:
                return found
    elif isinstance(value, list):
        for item in value:
            found = find_xml(item)
            if found is not None:
                return found
    return None


def inspect_envelope(envelope):
    xml_text = find_xml(envelope)
    report = {"xml_parse_status": "unavailable", "nmap_completion": "unknown",
              "tcp22_ssh_candidates": []}
    if xml_text is None:
        return report
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        report["xml_parse_status"] = "failed: " + str(exc)
        return report
    report["xml_parse_status"] = "parsed"
    finished = root.find("./runstats/finished")
    if finished is not None:
        report["nmap_completion"] = finished.get("exit", "finished; exit status unspecified")
        report["nmap_finished_summary"] = finished.attrib
    for host in root.findall("./host"):
        address = next((item.get("addr") for item in host.findall("./address")
                        if item.get("addrtype") == "ipv4"), None)
        for port in host.findall("./ports/port"):
            state = port.find("state")
            if port.get("protocol") != "tcp" or port.get("portid") != "22" or state is None or state.get("state") != "open":
                continue
            service = port.find("service")
            attrs = service.attrib if service is not None else {}
            evidence_text = " ".join(str(attrs.get(k, "")) for k in ("name", "product", "version", "tunnel", "extrainfo"))
            if "ssh" in evidence_text.lower():
                report["tcp22_ssh_candidates"].append({"address": address, "port": 22,
                                                        "state": "open", "service_evidence": attrs})
    return report


def scan_batch(octet):
    batch = "192.168.%d.0/24" % octet
    argv = ["nmap", "-n", "-Pn", "-sV", "--version-light", "-p", "22", "--open",
            "-T4", "--max-retries", "1", "--host-timeout", "12s",
            "--exclude", EXCLUDED, "-oX", "-", batch]
    try:
        envelope = framework_evidence.run_tool(argv)
        return batch, envelope, inspect_envelope(envelope), None
    except Exception as exc:
        return batch, None, {"xml_parse_status": "unavailable", "nmap_completion": "unknown",
                             "tcp22_ssh_candidates": []}, repr(exc)


def main():
    batches = list(range(256))
    emitted = 0
    completed_xml = 0
    candidates = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=WORKERS) as pool:
        futures = [pool.submit(scan_batch, octet) for octet in batches]
        for future in concurrent.futures.as_completed(futures):
            batch, envelope, assessment, error = future.result()
            emitted += 1
            if assessment.get("nmap_completion") == "success":
                completed_xml += 1
            candidates.extend(assessment.get("tcp22_ssh_candidates", []))
            record = {"batch": batch, "scope": SCOPE, "excluded_addresses": EXCLUDED.split(","),
                      "tool_envelope": envelope, "batch_assessment": assessment}
            if error is not None:
                record["invocation_error"] = error
            print(json.dumps(record, ensure_ascii=False, default=str), flush=True)
    print(json.dumps({"survey_summary": {"planned_batches": len(batches),
                                         "emitted_batch_results": emitted,
                                         "xml_batches_reporting_success": completed_xml,
                                         "tcp22_ssh_candidates": candidates,
                                         "coverage_note": "Only batches with parseable Nmap XML and a successful finished status are counted as completed; other batch coverage remains unknown or incomplete."}},
                     ensure_ascii=False, default=str), flush=True)


if __name__ == "__main__":
    main()

