import concurrent.futures
import ipaddress
import json
import sys

import framework_evidence

NETWORK = ipaddress.ip_network("192.168.0.0/16")
EXCLUDED = ["192.168.122.1", "192.168.0.5"]
MAX_WORKERS = 32


def emit(record):
    print(json.dumps(record, ensure_ascii=False, default=str), flush=True)


def scan_batch(batch):
    argv = [
        "nmap", "-n", "-Pn", "-p", "22", "-sV", "--version-light",
        "--open", "--reason", "-T4", "--max-retries", "1",
        "--host-timeout", "20s", "-oX", "-", "--exclude",
        ",".join(EXCLUDED), str(batch)
    ]
    try:
        envelope = framework_evidence.run_tool(argv)
        return {"batch": str(batch), "argv": argv, "tool_envelope": envelope}
    except Exception as exc:
        return {
            "batch": str(batch),
            "argv": argv,
            "execution_error": type(exc).__name__ + ": " + str(exc)
        }


def main():
    batches = list(NETWORK.subnets(new_prefix=24))
    emit({
        "record_type": "survey_start",
        "network": str(NETWORK),
        "batch_prefix": 24,
        "batch_count": len(batches),
        "excluded": EXCLUDED,
        "workers": MAX_WORKERS,
        "method": "parallel Nmap TCP/22 service identification"
    })

    completed_records = 0
    with concurrent.futures.ThreadPoolExecutor(max_workers=MAX_WORKERS) as pool:
        futures = {pool.submit(scan_batch, batch): batch for batch in batches}
        for future in concurrent.futures.as_completed(futures):
            batch = futures[future]
            try:
                record = future.result()
            except Exception as exc:
                record = {
                    "batch": str(batch),
                    "execution_error": type(exc).__name__ + ": " + str(exc)
                }
            emit({"record_type": "batch_result", **record})
            completed_records += 1

    emit({
        "record_type": "survey_end",
        "batches_scheduled": len(batches),
        "batch_result_records_emitted": completed_records,
        "coverage_note": (
            "A result record is not by itself proof that the Nmap scan completed. "
            "Use each tool envelope's process status, structured output, and raw "
            "streams; treat errors, timeouts, parser failures, and missing results "
            "as unresolved coverage. The two excluded addresses were omitted."
        )
    })


if __name__ == "__main__":
    main()

