import concurrent.futures
import ipaddress
import json
import re
import sys

import framework_evidence

SCOPE = ipaddress.ip_network("192.168.0.0/16")
EXCLUDED = {"192.168.0.5", "192.168.122.1"}
BATCH_PREFIX = 22
WORKERS = 32


def make_batches():
    return list(SCOPE.subnets(new_prefix=BATCH_PREFIX))


def run_batch(index, network):
    target = str(network)
    command = [
        "nmap", "-n", "-Pn", "-T4", "-sV", "--version-light", "--reason",
        "--open", "-p", "22", "--max-retries", "1", "--min-rate", "1000",
        "--host-timeout", "45s", "-oN", "-",
        "--exclude", ",".join(sorted(EXCLUDED)), target,
    ]
    try:
        envelope = framework_evidence.run_tool(command)
        if not isinstance(envelope, dict):
            return {
                "batch_index": index,
                "batch_range": target,
                "process_status": "uninterpretable_envelope",
                "exit_code": None,
                "scan_complete": False,
                "nmap_summary": None,
                "ssh_candidates": [],
                "coverage_note": "Tool wrapper returned a non-object envelope; batch coverage is unknown.",
            }
        runs = envelope.get("tool_runs") or []
        run = runs[0] if runs and isinstance(runs[0], dict) else {}
        stdout = run.get("stdout") if isinstance(run.get("stdout"), str) else ""
        stderr = run.get("stderr") if isinstance(run.get("stderr"), str) else ""
        status = run.get("status", "unknown")
        exit_code = run.get("exit_code")

        candidates = []
        current_ip = None
        for line in stdout.splitlines():
            report = re.match(r"\s*Nmap scan report for\s+(\S+)", line)
            if report:
                token = report.group(1)
                try:
                    current_ip = str(ipaddress.ip_address(token))
                except ValueError:
                    current_ip = None
                continue
            port = re.match(r"\s*22/tcp\s+open\s+ssh(?:\s+(.*))?$", line)
            if port and current_ip and current_ip not in EXCLUDED:
                try:
                    in_scope = ipaddress.ip_address(current_ip) in SCOPE
                except ValueError:
                    in_scope = False
                if in_scope:
                    candidates.append({
                        "address": current_ip,
                        "service": "ssh",
                        "version_or_product": (port.group(1) or "").strip() or None,
                        "evidence": line.strip(),
                    })

        summaries = re.findall(r"^\s*Nmap done:.*$", stdout, flags=re.MULTILINE)
        summary = summaries[-1].strip() if summaries else None
        timeout_text = re.search(r"timed?\s*out|host timeout|incomplete", stdout + "\n" + stderr, re.IGNORECASE)
        complete = status == "completed" and exit_code == 0 and summary is not None and timeout_text is None
        if complete:
            note = "Nmap reported a completion summary with exit code 0; this does not establish endpoint identity beyond the recorded service evidence."
        elif status != "completed" or exit_code != 0:
            note = "The tool process did not report successful completion; batch coverage is incomplete or unknown."
        elif timeout_text:
            note = "Timeout or incomplete-scan text was observed; batch coverage is incomplete."
        else:
            note = "No Nmap completion summary was interpretable; batch coverage is unknown."
        result = {
            "batch_index": index,
            "batch_range": target,
            "process_status": status,
            "exit_code": exit_code,
            "scan_complete": complete,
            "nmap_summary": summary,
            "ssh_candidates": candidates,
            "coverage_note": note,
        }
        if stderr.strip():
            result["stderr_excerpt"] = stderr.strip()[:800]
        if not runs:
            result["coverage_note"] = "Tool envelope contained no tool run; batch coverage is unknown."
            result["scan_complete"] = False
        return result
    except Exception as exc:
        return {
            "batch_index": index,
            "batch_range": target,
            "process_status": "execution_error",
            "exit_code": None,
            "scan_complete": False,
            "nmap_summary": None,
            "ssh_candidates": [],
            "coverage_note": "The tool invocation raised an exception; batch coverage is unknown.",
            "error": str(exc)[:800],
        }


def main():
    batches = make_batches()
    with concurrent.futures.ThreadPoolExecutor(max_workers=WORKERS) as pool:
        futures = {
            pool.submit(run_batch, index, network): index
            for index, network in enumerate(batches)
        }
        for future in concurrent.futures.as_completed(futures):
            try:
                record = future.result()
            except Exception as exc:
                index = futures[future]
                record = {
                    "batch_index": index,
                    "batch_range": str(batches[index]),
                    "process_status": "worker_error",
                    "exit_code": None,
                    "scan_complete": False,
                    "nmap_summary": None,
                    "ssh_candidates": [],
                    "coverage_note": "Batch worker failed; coverage is unknown.",
                    "error": str(exc)[:800],
                }
            print(json.dumps(record, separators=(",", ":")), flush=True)


if __name__ == "__main__":
    main()

