import concurrent.futures
import ipaddress
import json
import re
import sys

import framework_evidence

NETWORK = ipaddress.ip_network("192.168.0.0/16")
EXCLUDED = {"192.168.122.1", "192.168.0.5"}
BATCH_PREFIX = 20
WORKERS = 16


def text_stream(value):
    """Find a raw stream in common evidence-envelope shapes without discarding it."""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        for key in ("stdout", "raw_stdout", "output"):
            candidate = value.get(key)
            if isinstance(candidate, str):
                return candidate
        for candidate in value.values():
            found = text_stream(candidate)
            if found:
                return found
    elif isinstance(value, list):
        for candidate in value:
            found = text_stream(candidate)
            if found:
                return found
    return ""


def envelope_value(envelope, keys):
    if isinstance(envelope, dict):
        for key in keys:
            if key in envelope:
                return envelope[key]
        for value in envelope.values():
            found = envelope_value(value, keys)
            if found is not None:
                return found
    elif isinstance(envelope, list):
        for value in envelope:
            found = envelope_value(value, keys)
            if found is not None:
                return found
    return None


def scan_batch(index, subnet):
    targets = [str(subnet)]
    argv = [
        "nmap", "-sn", "-n", "-T4", "--reason", "--max-retries", "1",
        "--host-timeout", "45s", "-PE", "-PS22,80,443", "-PA80,443",
        "--exclude", ",".join(sorted(EXCLUDED)), "-oG", "-", *targets,
    ]
    try:
        result = framework_evidence.run_tool(argv)
        return index, str(subnet), argv, result, ""
    except Exception as exc:
        return index, str(subnet), argv, None, "%s: %s" % (type(exc).__name__, exc)


def main():
    batches = list(NETWORK.subnets(new_prefix=BATCH_PREFIX))
    results = {}
    with concurrent.futures.ThreadPoolExecutor(max_workers=WORKERS) as pool:
        futures = [pool.submit(scan_batch, i, subnet) for i, subnet in enumerate(batches)]
        for future in concurrent.futures.as_completed(futures):
            item = future.result()
            results[item[0]] = item

    for index in range(len(batches)):
        _, subnet, argv, envelope, error = results[index]
        if envelope is not None:
            # Preserve and emit the complete helper envelope, including raw streams.
            print(json.dumps(envelope, sort_keys=True, default=str), flush=True)
        stdout = text_stream(envelope) if envelope is not None else ""
        exit_code = envelope_value(envelope, ("exit_code", "returncode")) if envelope is not None else None
        process_status = envelope_value(envelope, ("status", "process_status")) if envelope is not None else None
        addresses = sorted(set(re.findall(r"(?m)^Host:\s+([0-9.]+)\s+.*?Status:\s+Up\b", stdout)))
        addresses = [addr for addr in addresses if addr not in EXCLUDED]
        summary_matches = re.findall(
            r"(?im)^#?\s*Nmap done[^\n]*?([0-9]+) IP addresses?\s*\(([^)]*)\)\s*scanned",
            stdout,
        )
        summary = None
        scanned_count = None
        if summary_matches:
            count_text, host_text = summary_matches[-1]
            scanned_count = int(count_text)
            summary = {"addresses_scanned": scanned_count, "host_summary": host_text.strip()}
        expected_count = sum(1 for addr in subnet.hosts() if str(addr) not in EXCLUDED)
        complete = (
            not error
            and exit_code == 0
            and summary is not None
            and scanned_count == expected_count
            and not re.search(r"(?i)(timed out|timeout|incomplete scan|failed to resolve)", stdout)
        )
        record = {
            "batch_index": index,
            "batch_range": subnet,
            "process_status": process_status,
            "exit_code": exit_code,
            "tool_error": error or None,
            "scan_complete": complete,
            "coverage": {
                "expected_addresses_after_exclusions": expected_count,
                "reported_addresses_scanned": scanned_count,
                "nmap_summary": summary,
            },
            "responsive_hosts": addresses,
            "coverage_note": (
                "Nmap completion summary and expected address count agree."
                if complete else
                "Coverage is incomplete or unverified; non-responses do not establish host absence."
            ),
            "command": argv,
        }
        print(json.dumps(record, sort_keys=True), flush=True)


if __name__ == "__main__":
    main()

