import concurrent.futures
import ipaddress
import json
import re
import sys

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"error": "framework_evidence import failed", "detail": str(exc)}), flush=True)
    raise SystemExit(1)

SCOPE = ipaddress.ip_network("192.168.0.0/16")
EXCLUDED = {"192.168.122.1", "192.168.0.5"}
WORKERS = 16


def find_field(value, names):
    if isinstance(value, dict):
        for name in names:
            if name in value:
                return value[name]
        for child in value.values():
            found = find_field(child, names)
            if found is not None:
                return found
    elif isinstance(value, list):
        for child in value:
            found = find_field(child, names)
            if found is not None:
                return found
    return None


def stream_text(value):
    if isinstance(value, str):
        return value
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False, default=str)
    return "" if value is None else str(value)


def scan_batch(index, network):
    excluded_here = sorted(address for address in EXCLUDED if ipaddress.ip_address(address) in network)
    expected = network.num_addresses - len(excluded_here)
    exclude_arg = ",".join(sorted(EXCLUDED))
    argv = [
        "nmap", "-sn", "-n", "-T4", "--max-retries", "1",
        "--host-timeout", "20s", "-oG", "-", "--exclude", exclude_arg,
        str(network),
    ]
    try:
        result = run_tool(argv)
    except Exception as exc:
        return index, network, expected, None, {"invocation_error": str(exc)}

    stdout = stream_text(find_field(result, ("stdout",)))
    stderr = stream_text(find_field(result, ("stderr",)))
    exit_code = find_field(result, ("exit_code", "returncode"))
    hosts = set()
    for match in re.finditer(r"(?m)^Host:\s+([0-9.]+)\b", stdout):
        address = match.group(1)
        try:
            parsed = ipaddress.ip_address(address)
        except ValueError:
            continue
        if parsed in SCOPE and address not in EXCLUDED:
            hosts.add(address)

    summary = re.search(r"(?m)^#\s*Nmap done\b[^\n]*?--\s*(\d+)\s+IP addresses?\s*\(", stdout)
    scanned = int(summary.group(1)) if summary else None
    complete = exit_code == 0 and summary is not None and scanned == expected
    if complete:
        note = "Nmap completion summary reports all expected non-excluded addresses scanned."
    elif summary is None:
        note = "No Nmap completion/address-count summary was present in the captured stdout."
    else:
        note = "Nmap summary address count or process exit status does not establish full batch coverage."

    record = {
        "batch_index": index,
        "batch_range": str(network),
        "process_status": find_field(result, ("status",)) or "returned",
        "exit_code": exit_code,
        "expected_addresses": expected,
        "summary_addresses_scanned": scanned,
        "scan_complete": complete,
        "responsive_hosts": sorted(hosts),
        "coverage_note": note,
        "tool_result": result,
    }
    return index, network, expected, complete, record


batches = list(SCOPE.subnets(new_prefix=22))
with concurrent.futures.ThreadPoolExecutor(max_workers=WORKERS) as pool:
    futures = [pool.submit(scan_batch, index, network) for index, network in enumerate(batches)]
    for future in concurrent.futures.as_completed(futures):
        try:
            index, network, expected, complete, record = future.result()
        except Exception as exc:
            record = {"process_status": "worker_error", "scan_complete": False, "coverage_note": str(exc)}
        print(json.dumps(record, ensure_ascii=False, separators=(",", ":"), default=str), flush=True)

