import json
import re
import sys

from framework_evidence import run_tool

TARGETS = ["192.168.0.1", "192.168.3.0", "192.168.65.3", "192.168.65.6"]
EXCLUDED = ["192.168.122.1", "192.168.0.5"]


def tool_runs(envelope):
    if isinstance(envelope, dict):
        runs = envelope.get("tool_runs")
        if isinstance(runs, list):
            return runs
        result = envelope.get("result")
        if isinstance(result, dict) and isinstance(result.get("tool_runs"), list):
            return result["tool_runs"]
    return []


def summarize(envelope):
    reports = {ip: {"host_report_seen": False, "tcp_22_line": None,
                    "service_identified_ssh": False} for ip in TARGETS}
    completion_lines = []
    runs = tool_runs(envelope)
    for run in runs:
        if not isinstance(run, dict):
            continue
        stdout = run.get("stdout")
        if not isinstance(stdout, str):
            continue
        current_ip = None
        for line in stdout.splitlines():
            match = re.search(r"Nmap scan report for (?:[^ (]+ \()?([0-9]+\.[0-9]+\.[0-9]+\.[0-9]+)\)?$", line)
            if match:
                current_ip = match.group(1)
                if current_ip in reports:
                    reports[current_ip]["host_report_seen"] = True
                continue
            if line.startswith("Nmap done:"):
                completion_lines.append(line)
            if current_ip in reports and re.match(r"^22/tcp\s+", line):
                reports[current_ip]["tcp_22_line"] = line.strip()
                fields = line.split()
                if len(fields) >= 3:
                    state = fields[1].lower()
                    service_and_version = " ".join(fields[2:]).lower()
                    reports[current_ip]["service_identified_ssh"] = (
                        state == "open" and
                        (fields[2].lower() == "ssh" or "openssh" in service_and_version or
                         re.search(r"\bssh\b", service_and_version) is not None)
                    )
    return reports, completion_lines, runs


argv = [
    "nmap", "-n", "-Pn", "-sV", "-p", "22", "-T4", "--reason",
    "--exclude", ",".join(EXCLUDED), *TARGETS
]
try:
    evidence = run_tool(argv)
    per_host, completion_lines, runs = summarize(evidence)
    output = {
        "purpose": "TCP/22 service identification on responsive hosts from partial discovery evidence",
        "targets": TARGETS,
        "excluded": EXCLUDED,
        "per_host": per_host,
        "tool_run_status": [
            {"status": run.get("status"), "exit_code": run.get("exit_code")}
            for run in runs if isinstance(run, dict)
        ],
        "nmap_completion_lines": completion_lines,
        "scan_completion_summary_seen": bool(completion_lines),
        "coverage_limitation": "Only these four hosts from the available partial discovery output were examined. The earlier discovery timed out; this scan does not establish coverage of all responsive hosts in 192.168.0.0/16.",
        "raw_tool_evidence": evidence,
    }
    print(json.dumps(output, ensure_ascii=False))
except Exception as exc:
    print(json.dumps({
        "purpose": "TCP/22 service identification",
        "targets": TARGETS,
        "excluded": EXCLUDED,
        "error": type(exc).__name__ + ": " + str(exc),
        "coverage_limitation": "The scan result could not be obtained or interpreted; no service findings are asserted. Discovery coverage was partial.",
    }, ensure_ascii=False))
    sys.exit(1)
